Here is a simpler HTML test case:

```
<!doctype html>
<html>
<head>
</head>
<body>
  <div class="s-hits" id="hits"></div>

  <script src="https://cdn.jsdelivr.net/g/instantsearch.js@1.3.0"></script>
  <script>
    var search = instantsearch({
      appId: 'MXM0JWJNIW',
      apiKey: 'ff7b0847d8705c279222272303e68527',
      indexName: 'steamdb'
    });

    search.addWidget(
      instantsearch.widgets.hits({
        container: '#hits',
        hitsPerPage: 20,
        templates: {
          item: '{{name}}'
        }
      })
    );

    search.start();
  </script>
</body>
</html>
```

